def enrich(bank):
    for q in bank:
        if q.get('topic')=='भीड़ में खोया आदमी':
            q['prompt']='लेखक कहाँ और किस उद्देश्य से जाता है? [2]\nदीनानाथ की स्थिति से रोजगार की कौन-सी समस्या स्पष्ट होती है? [2]\nआवास और चिकित्सा के दो प्रसंग जनसंख्या के दबाव को कैसे दिखाते हैं? [3]\nकहानी के शीर्षक और सामाजिक व्यंग्य का संबंध स्पष्ट कीजिए। [3]'
            q['answerSource']='https://www.hindikunj.com/2022/06/bheed-me-khoya-aadmi.html'
        if q.get('category')=='literature' and q['topic'] in MODELS:
            q['answer']='\n\n'.join(f'({i+1}) [{[2,2,3,3][i]} अंक] {answer}' for i,answer in enumerate(MODELS[q['topic']]))
        elif q.get('category')=='literature':
            # Keep the known factual answer and remove empty examiner instructions.
            q['answer']=q['answer'].replace('निर्धारित अध्याय 14–26 के सही प्रसंगों से उत्तर समर्थित करें।','मीनू का वकालत की ओर बढ़ना विवाह से स्वतंत्र व्यक्तिगत पहचान स्थापित करता है।')
    return bank
